import{RETURN_QUEST_PATHS,RETURN_QUEST_GOLD,returnQuestProgress}from'./expedition-return-quest.mjs';import{EXPEDITIONS,GEAR}from'./expedition-data.mjs';import{equipmentStats}from'./expedition-equipment-view.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function returnQuestView(g){const p=returnQuestProgress(g),q=g.returnQuest,a=q?.lastAttempt,path=q?.steps[1]&&RETURN_QUEST_PATHS[q.steps[1].route];return `<section class="guild-panel return-quest" data-guild-pane="journey" data-story-book="returnquest"><p class=eyebrow>单人故事 / 归岸证词 · 项目原创</p><h2>把归来的人，写回岸上的簿册。</h2><p>引航员奈芮记得路，却还不知道该把哪一种回答带回码头。接取后先让她活着抵达，再选择留下能亲口回答的敌方头领，或拆开追击归客的猎令。没有哪条路被当成所有人的正确答案。</p><p class=story-progress role=status>${p.started?'实录 '+p.completed+'/2 · 第'+q.startedAt+'次起接取 · ':''}${esc(p.reason)}</p>${!p.started?`<button data-returnquest-start ${p.canStart?'':'disabled'}>接取归岸证词</button>`:''}<div class=story-steps><article><h3>第一段 · 让引航员抵岸</h3><p>完整通过退潮护送，奈芮以正生命归来。六人存活不能代替护送对象存活；接取前的旧通关不计入本段。</p>${q?.steps[0]?`<p class=return-proof>第${q.steps[0].id}次正式护送已领取 · 奈芮生命${q.steps[0].outcome.escortHP}/90。</p>`:p.started?`<button data-returnquest-prepare ${g.pending?'disabled':''}>准备退潮护送 →</button>`:''}</article><article><h3>第二段 · 选择带回怎样的回答</h3>${Object.entries(RETURN_QUEST_PATHS).map(([route,v])=>`<article data-returnquest-route="${route}"><h4>${esc(v.name)} · ${EXPEDITIONS[route].name}</h4><p>${esc(v.condition)}。普通通关奖励照常；招抚少一名头领仍可能通关，但不完成本支证词。</p><p>此路交付：${RETURN_QUEST_GOLD}金币与${GEAR[v.gear].name}。</p><small>${esc(equipmentStats(v.gear))}</small>${p.started&&p.completed===1?`<button data-returnquest-path="${route}" ${g.pending||p.selected===route?'disabled':''}>${p.selected===route?'已选择此路':'选择此路'}</button>`:''}</article>`).join('')}${p.completed===1&&p.selected?`<button data-returnquest-prepare ${g.pending?'disabled':''}>准备所选归岸通路 →</button>`:''}${q?.steps[1]?`<p class=return-proof>第${q.steps[1].id}次${EXPEDITIONS[q.steps[1].route].name}已领取，${q.steps[1].route==='parleyquay'?'两名头领以正生命投降，证词来自真实战斗。':'本次实际完成拆令，未伪称取得头领口述。'}</p>`:''}</article></div>${a?`<p class=return-attempt>上次实际回报：第${a.id}次${EXPEDITIONS[a.route].name} · ${a.won?'完整通关':'未完成通关'}${a.escortHP!==null?' · 引航员生命'+a.escortHP+'/90':a.route==='parleyquay'?' · '+a.leaders+'/2名头领投降':''}。普通报酬已按当次结果结算，未达成本段可继续准备。</p>`:''}${path?`<article class=story-ending><h3 ${p.ending?'data-journey-receipt':''}>${esc(path.ending)}</h3><p>${esc(path.text)}</p>${p.ending?'<p>已亲自交付，金币与遗物已入仓；不会重复发奖。</p><button data-guild-tab=equipment>去仓库分配 →</button>':`<p>两段普通收益已经分别结算。本次仅另领一次故事报酬：${RETURN_QUEST_GOLD}金币与${GEAR[path.gear].name}，不加经验、不自动分配。</p><button data-returnquest-deliver ${p.canClaim?'':'disabled'}>亲自交付归岸证词</button>`}</article>`:''}<p>这是有限的项目原创故事，不是原版WoD任务。路线与战术仍可自由探索，当前未完成分支可改选，已完成实录不改写。实验、历史重演、收藏和未领取远征不推进；实录随公会及整档保存，最近20条履历滚出也保留。</p></section>`;}
